  }
  button:hover{background:#f1f5f9;}
  button.primary{background:#2563eb;border-color:#2563eb;color:#fff;}
  button.primary:hover{background:#1d4ed8;}

  /* ---------- 步骤 ---------- */
  .stepper{margin-top:14px;padding:14px 18px 16px;}
  .step-buttons{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:13px;}
  .step-btn{
    border-radius:999px;padding:6px 14px;font-size:12.5px;border:1px solid #cbd5e1;
